int main(){try{set_worker_executable(path_from_utf8(CAD_SERVICE_EXE));geometry();captured();std::cout<<checks<<" mesh reconstruction checks passed\n";return 0;}catch(const Error& e){std::cerr<<"After "<<checks<<": "<<e.code<<": "<<e.what()<<" "<<e.details.dump()<<'\n';return 1;}catch(const std::exception& e){std::cerr<<"After "<<checks<<": "<<e.what()<<'\n';return 1;}}
